    let filter = contract.GetEventBySignature("0x7a91e3265b1469f01a44971ff760e073f1d8a3c0d9459bb619329319114c7a3e").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeFeeSplitUpdatedEvent (contract: Contract) (log: FilterLog) : FeeSplitUpdatedEvent =
    let decoded = contract.GetEventBySignature("0x7a91e3265b1469f01a44971ff760e073f1d8a3c0d9459bb619329319114c7a3e").DecodeAllEventsForEvent<FeeSplitUpdatedEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryFeeSplitUpdated (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<FeeSplitUpdatedEvent>>()
        let event = contract.GetEventBySignature("0x7a91e3265b1469f01a44971ff760e073f1d8a3c0d9459bb619329319114c7a3e")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<FeeSplitUpdatedEvent>(decodeFeeSplitUpdatedEvent contract log, log))
        return result
    }

